 * 
 * <p>
 * This is accomplished by delegating to the int access generator with type conversion.
 */
public class FloatAccessGen : SimpleAccessGen<TFloat, FloatJitType>
{	public static readonly FloatAccessGen BE = new(IntAccessGen.BE);
	public static readonly FloatAccessGen LE = new(IntAccessGen.LE);


	IntAccessGen intGen;

	private FloatAccessGen(IntAccessGen intGen) {
		this.intGen = intGen;
	}

	/* @Override */
	public Emitter<Ent<N, TFloat>> genReadToStack<THIS, N>/* where THIS : JitCompiledPassage where N : Next */(
			Emitter<N> em, Local<TRef<THIS>> localThis, JitCodeGenerator<THIS> gen, Varnode vn) {
